const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="empty">You're all caught up.</td></tr>`}</tbody></table></div>`;
const card=(title,body,action='',cls='')=>`<section class="card ${cls}"><div class="card-head"><h3>${title}</h3>${action}</div>${body}</section>`;
const link=(t,p)=>`<button class="text-link" data-page="${p}">${t} ↗</button>`;
const summary=items=>`<div class="summary-grid ${items.length===3?'three':''}">${items.map(([l,v,n,u])=>`<div class="card summary ${u?'urgent':''}"><p>${l}</p><strong>${v}</strong><small>${n}</small></div>`).join('')}</div>`;
const announcementBody=()=>announcements.slice(0,3).map(a=>`<div class="announcement"><strong>${esc(a[0])}</strong><p>${esc(a[1])}</p><small>${esc(a[2])}</small></div>`).join('');
function landing(){document.getElementById('app').innerHTML=`<div class="container"><nav class="site-nav" aria-label="Main navigation">${brand()}<div class="nav-links"><a href="#home">Home</a><a href="#features">Features</a><a href="#how-it-works">How It Works</a><a href="#security">Security</a><a href="#contact">Contact</a></div><div class="nav-actions">${btn('Login','login','ghost')}${btn('Register '+icon('arrow'),'register','primary')}<button class="mobile-toggle" data-action="public-menu" aria-label="Toggle navigation">${icon('menu')}</button></div></nav><main><section class="hero" id="home"><div class="reveal"><div class="pill"><span class="dot"></span> BUILT FOR CAMPUS LIFE</div><h1>Smarter Hostel<br>Management.<br><span>Safer Student Living.</span></h1><p>Manage accommodation, passes, complaints, mentoring and hostel operations from one secure platform.</p><div class="hero-buttons">${btn('Student Registration '+icon('arrow'),'register','primary')}${btn('Login '+icon('out'),'login')}</div><div class="hero-note">${icon('shield')} A little less paperwork. A lot more peace of mind.</div></div><div class="hero-visual reveal"><img class="campus" src="https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1100&q=85" alt="University graduates celebrating together outdoors" fetchpriority="high"><div class="image-tag">${icon('leaf')} Better spaces. Better student experiences.</div><div class="visual-card"><span class="icon-box">${icon('building')}</span><div><strong>A better place to belong.</strong><p>Connected campuses. Supported students.</p></div><span class="check">${icon('check')}</span></div></div></section><section class="stats-band" aria-label="Illustrative aggregate statistics"><div class="stats-intro"><strong>Built for institutions.</strong><br>Illustrative platform figures.</div><div class="public-stat"><strong>1</strong><p>Institution</p></div><div class="public-stat"><strong>3</strong><p>Hostels managed</p></div><div class="public-stat"><strong>720</strong><p>Total accommodation capacity</p></div></section>${roleExplorer()}<section class="section" id="features"><div class="section-heading"><span class="eyebrow">ONE PLATFORM. EVERYDAY SIMPLIFIED.</span><h2>Everything your hostel needs.</h2><p>Thoughtful tools that make campus living work better for everyone.</p></div><div class="feature-grid">${[['bed','Room & Bed Management','A clear view of accommodation. Simplify room allocations and make every space count.'],['pass','Digital Hostel Passes','Quick QR passes for daily movement. Approved Long Passes for planned time away.'],['message','Complaint Tracking','Give every concern a clear path to resolution. Keep students informed at every step.'],['qr','QR Entry/Exit','Make gate check-ins simple, with secure digital passes and accountable access.'],['users','Student Mentoring','Connect students with the right guidance, meaningful conversations and support.'],['chart','Administrative Reports','Turn everyday records into useful insights for better institutional decisions.']].map(([i,t,d])=>`<article class="feature-card"><span class="icon-box">${icon(i)}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section></main></div><section class="workflow-section" id="how-it-works"><div class="container section"><div class="section-heading"><span class="eyebrow">A SIMPLE PATH TO SETTLING IN</span><h2>From registration to feeling at home.</h2><p>One connected journey. Less running around.</p></div><div class="workflow">${[['Register','Start with your invitation'],['Admin Verification','Your details, checked securely'],['Hostel Allocation','Find your place on campus'],['Student Dashboard','Everything in one view'],['Hostel Services','Support, whenever you need it']].map(([t,d],i)=>`<div class="step"><span class="step-number">0${i+1}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></section><div class="container"><section class="section security" id="security"><div><span class="eyebrow">TRUST AT THE FOUNDATION</span><h2>Student life is personal.<br>We design to keep it that way.</h2><p>Privacy and accountability belong at the heart of every campus. Our security requirements guide every workflow.</p></div><div class="security-grid">${[['users','Role-based access','The right access for students, admins, wardens and mentors.'],['lock','Secure authentication','Designed for verified accounts and privileged-access MFA.'],['shield','Protected student records','Private information stays within authorized workflows.'],['file','Audit logging','A traceable record of important institutional actions.']].map(([i,t,d])=>`<div class="security-item">${icon(i)}<div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section><section class="contact" id="contact"><div><span class="eyebrow">LET'S BUILD A BETTER CAMPUS</span><h2>Good hostel operations.<br>Great student experiences.</h2><p>Interested in Hostel Ops for your institution?<br>Tell us a little about your campus.</p><p style="font-size:13px">Frontend preview · Contact delivery is not connected.</p></div><form id="contact-form" class="form-grid"><div><label for="contact-name">Your name</label><input id="contact-name" name="name" placeholder="Full name" required></div><div><label for="institution">Institution</label><input id="institution" name="institution" placeholder="College or university" required></div><div class="span-2"><label for="contact-email">Work email</label><input id="contact-email" name="email" type="email" placeholder="you@institution.edu" required></div><div class="span-2"><label for="contact-message">How can we help?</label><textarea id="contact-message" name="message" placeholder="Tell us about your hostel management needs" required></textarea></div><div class="span-2"><button class="btn primary" type="submit">Preview enquiry ${icon('arrow')}</button></div></form></section><footer class="footer">${brand()}<div class="footer-links"><a href="#features">About</a><button class="text-link" data-action="privacy">Privacy</button><a href="#contact">Contact</a><a href="#security">Security</a></div><p>© 2026 Hostel Ops. A better campus, together.</p></footer></div>`;}
function complaintTable(student=false){return table(student?['Complaint ID','Category','Status','Updated']:['Complaint ID','Student / Room','Category','Status','Priority','Action'],complaints.filter(c=>student?c.student.startsWith('Aarav'):c.status!=='Resolved').map(c=>student?[c.id,esc(c.category),badge(c.status),c.date]:[c.id,c.student,esc(c.category),badge(c.status),c.priority,btn('Update','update:'+c.id,'small')]));}
function gateTable(student=false){return table(student?['Date','Exit','Entry','Status']:['Student','Movement','Time','Gate'],student?[['24 Sep 2026','4:15 PM','6:42 PM',badge('Returned')],['22 Sep 2026','9:10 AM','12:35 PM',badge('Returned')]]:[['Aarav Sharma',badge('Entry'),'6:42 PM','Main gate'],['Rohan Mehta',badge('Exit'),'5:30 PM','Main gate'],['Aditya Kumar',badge('Entry'),'5:18 PM','East gate']]);}
function passTable(){return table(['Student','Room','Reason','Departure','Expected Return','Actions'],passes.filter(p=>p.status==='Pending').map(p=>[p.name,p.room,esc(p.reason),p.departure,p.return,`<div class="action-group">${btn('Approve','approve:'+passes.indexOf(p),'small primary')}${btn('Reject','reject:'+passes.indexOf(p),'small danger')}${btn('Details','pass-detail:'+passes.indexOf(p),'small')}</div>`]));}
function studentDashboard(){let p=passes[0],s=currentStudent(),a=s.allocation;return `<div class="dashboard-grid"><section class="card identity"><span class="eyebrow">YOUR HOME ON CAMPUS</span><h3 style="margin-top:9px">A place to call your own.</h3><div class="identity-row">${[['Hostel',a?.hostel||'Awaiting allocation'],['Room',a?.room||'Not allocated'],['Bed',a?.bed||'Not allocated'],['Academic Year',s.academicYear],['Study year','Year '+s.studyYear]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div></section>${card('Your mentor',`<div class="mentor-info"><img src="https://images.unsplash.com/photo-1580489944761-15a19d654956?w=100&h=100&fit=crop&crop=faces" alt="Demo mentor profile"><div><strong>Dr. Meera Nair</strong><p>Department of Computer Science</p></div></div>${btn('Request a session','session','small')}`)}</div>${passChoices()}<div class="quick-actions">${[['message','Raise Complaint','complaint'],['qr','Quick Pass QR','quick-pass'],['pass','Request Long Pass','long-pass'],['users','Contact Mentor','session']].map(([i,t,a])=>`<button class="quick-action" data-action="${a}"><span class="icon-box">${icon(i)}</span>${t}</button>`).join('')}</div><div class="dashboard-grid"><div class="stack">${card(s.allocation?'Approved Long Pass':'Previous Long Pass',`<div style="display:flex;justify-content:space-between;font-size:15px"><span>Weekend visit · Family visit</span>${badge(s.allocation?p.status:'Archived')}</div><div class="pass-details"><div><small>Departure</small><strong>${p.departure}</strong></div><div><small>Expected return</small><strong>${p.return}</strong></div></div><div class="pass-foot"><span>PASS-2026-0184</span>${btn('View Long Pass','pass-detail:0','small')}</div>`,link('All passes','Passes'))}${card('Recent complaints',complaintTable(true),link('View all','Complaints'))}${card('Recent entry / exit',gateTable(true),link('View history','Entry / Exit'))}</div><div class="stack" style="align-content:start">${card('Announcements',announcementBody(),link('View all','Announcements'))}${card('Need a hand?',`<p style="font-size:15px;color:var(--muted)">Your hostel team is here to help. Reach out about accommodation or campus services.</p>${btn('Contact hostel office','office','small')}`)}</div></div>`;}
function wardenDashboard(){return summary([['Total Residents',hostelInventory()[0].occupied,'Maple House'],['Currently Out','18','Approved passes'],['Overdue Returns','1','Requires your attention',true],['Pending Pass Requests',passes.filter(p=>p.status==='Pending').length,'Awaiting review'],['Open Complaints',complaints.filter(c=>c.status==='Open').length,'Awaiting resolution']])+`<div class="stack">${card('Overdue students',table(['Student','Room','Expected return','Time overdue','Contact'],[['Karan Joshi','B-208','24 Sep, 10:00 PM',badge('Overdue')+' 10 hours',`<div class="action-group">${btn('Student','contact-student','small')}${btn('Guardian contact','guardian','small')}</div>`]]),'<span class="badge overdue">Action required</span>')}${card('Pending Long Pass requests',passTable(),link('View all','Pass Requests'))}${card('Open complaints',complaintTable(),link('View all','Complaints'))}<div class="dashboard-grid">${card('Recent gate activity',gateTable(),link('View all','Gate Activity'))}${card('Hostel announcements',announcementBody(),btn('+ Create','announcement','small'))}</div></div>`;}
function registrationTable(){return table(['Student','College ID','Course','Year','Documents','Status',''],registrations.map((r,i)=>[...r.slice(0,4),btn('View','documents:'+i,'small'),badge(r[5]),btn('Review','review:'+i,'small')]));}
function roomTable(){return table(['Hostel','Total Beds','Occupied','Available','Maintenance'],hostelInventory().map(h=>[h.name,h.total,h.occupied,h.available,h.maintenance]));}
function roomMapCard(){
  const data=roomMapData();
  const hostels=['Maple House','Cedar House','Oak House'];
  const hData=data.filter(r=>r.hostel===roomMapHostel);
  const filtered=roomMapFilter==='Occupied only'?hData.filter(r=>r.beds.some(b=>b.student)):roomMapFilter==='Vacant only'?hData.filter(r=>r.beds.some(b=>!b.student)):hData;
  const totalBeds=hData.length*2;
  const occupiedBeds=hData.reduce((n,r)=>n+r.beds.filter(b=>b.student).length,0);
  const vacantBeds=totalBeds-occupiedBeds;
  const personIcon='<svg viewBox="0 0 20 20" aria-hidden="true" class="bs-icon"><circle cx="10" cy="5" r="3" fill="#fff"/><path d="M4 17c0-3.5 2.7-6 6-6s6 2.5 6 6" fill="#fff"/></svg>';
  const plusIcon='<svg viewBox="0 0 20 20" aria-hidden="true" class="bs-icon"><path d="M10 4v12M4 10h12" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/></svg>';
  function bedBtn(b,hostel,room){
    const ariaLabel=esc(hostel)+' '+esc(room)+' bed '+b.bed+(b.student?', occupied by '+esc(b.student.name):', vacant');
    if(b.student){
      return '<button class="bs-bed bs-bed-occ" data-action="rm-bed:'+esc(b.student.id)+'" title="'+esc(b.student.name)+'" aria-label="'+ariaLabel+'">'+personIcon+'</button>';
    }
    return '<button class="bs-bed bs-bed-vac" data-action="rm-vacant:'+esc(hostel)+'|'+esc(room)+'|'+b.bed+'" title="Vacant" aria-label="'+ariaLabel+'">'+plusIcon+'</button>';
  }
  function roomTile(r){
    const b0=bedBtn(r.beds[0],roomMapHostel,r.room);
    const b1=bedBtn(r.beds[1],roomMapHostel,r.room);
    return '<div class="bs-room"><div class="bs-beds">'+b0+b1+'</div><span class="bs-rnum">'+esc(r.room)+'</span></div>';
  }
  const floorMap={};
  filtered.forEach(r=>{(floorMap[r.floor]||(floorMap[r.floor]=[])).push(r);});
  const floorsHtml=Object.keys(floorMap).sort((a,b)=>a-b).map(floor=>{
    const rooms=floorMap[floor];
    const busRows=[];
    for(let i=0;i<rooms.length;i+=4){
      const r0=rooms[i]   ? roomTile(rooms[i])   : '<div class="bs-room bs-room-ph"></div>';
      const r1=rooms[i+1] ? roomTile(rooms[i+1]) : '<div class="bs-room bs-room-ph"></div>';
      const r2=rooms[i+2] ? roomTile(rooms[i+2]) : '<div class="bs-room bs-room-ph"></div>';
      const r3=rooms[i+3] ? roomTile(rooms[i+3]) : '<div class="bs-room bs-room-ph"></div>';
      busRows.push('<div class="bs-row"><div class="bs-left">'+r0+r1+'</div><div class="bs-aisle" aria-hidden="true"></div><div class="bs-right">'+r2+r3+'</div></div>');
    }
    return '<div class="bs-floor"><h4 class="bs-floor-label">Floor '+floor+'</h4><div class="bs-bus">'+busRows.join('')+'</div></div>';
  }).join('');
  const tabs=hostels.map(h=>'<button class="rm-tab'+(h===roomMapHostel?' rm-tab-active':'')+'" data-action="rm-hostel:'+h+'">'+esc(h)+'</button>').join('');
  const filterBtns=['All','Occupied only','Vacant only'].map(f=>'<button class="rm-filter'+(f===roomMapFilter?' rm-filter-active':'')+'" data-action="rm-filter:'+f+'">'+f+'</button>').join('');
  const legend='<div class="rm-legend"><span class="rm-legend-item"><span class="bs-leg bs-leg-occ"></span>Occupied</span><span class="rm-legend-item"><span class="bs-leg bs-leg-vac"></span>Vacant</span></div>';
  const counts='<div class="rm-counts"><strong>'+occupiedBeds+'</strong> occupied / <strong>'+vacantBeds+'</strong> vacant / <strong>'+totalBeds+'</strong> total beds</div>';
  return '<div class="rm-wrap"><div class="rm-hostel-tabs" role="group" aria-label="Select hostel">'+tabs+'</div>'+legend+'<div class="rm-toolbar">'+counts+'<div class="rm-filters" role="group" aria-label="Filter beds">'+filterBtns+'</div></div>'+(floorsHtml||'<p class="muted">No rooms match this filter.</p>')+'</div>';
}
function roomMapMini(){
  const data=roomMapData();
  const rows=hostelInventory().map(h=>{
    const hRooms=data.filter(r=>r.hostel===h.name);
    const total=hRooms.length*2;
    const occ=hRooms.reduce((n,r)=>n+r.beds.filter(b=>b.student).length,0);
    const bedDots=hRooms.map(r=>
      r.beds.map(b=>'<span class="rmm-dot '+(b.student?'rmm-occ':'rmm-vac')+'" title="'+esc(r.room)+' bed '+b.bed+(b.student?': '+esc(b.student.name):', vacant')+'"></span>').join('')
    ).join('');
    return '<div class="rmm-hostel"><div class="rmm-top"><span class="rmm-name">'+esc(h.name)+'</span><span class="rmm-stat"><strong>'+occ+'</strong> / '+total+' beds occupied</span></div><div class="rmm-dots">'+bedDots+'</div></div>';
  }).join('');
  return '<div class="rmm-wrap">'+rows+'<div class="rmm-link">'+
    '<button class="text-link" data-page="Rooms & Beds">Open Room Map ↗</button></div></div>';
}
function occupancy(){return hostelInventory().map(h=>[h.name,h.occupied,h.total]).map(([n,o,t])=>`<div class="occupancy-row"><span>${n}</span><div class="bar" role="img" aria-label="${n}: ${o} of ${t} beds occupied"><span style="width:${o/t*100}%"></span></div><span>${o} / ${t}</span></div>`).join('')+'<p style="font-size:13px;color:var(--muted)">Occupied beds / total capacity · Demo academic year 2026–27</p>';}
function adminDashboard(){return summary([['Total Students','632','Across all hostels'],['Total Hostels','3','Active this academic year'],['Total Beds','720','Institutional capacity'],['Available Beds',hostelInventory().reduce((n,h)=>n+h.available,0),'Ready for allocation'],['Pending Registrations',registrations.filter(r=>r[5]==='Pending').length,'Awaiting verification']])+`<div class="dashboard-grid">${card('Hostel occupancy',roomMapMini())}${card('Quick actions',`<div class="form-grid">${['Add Hostel','Add Room','Allocate Student','Create Mentor','Add Warden','Year Promotion','Generate Report'].map(a=>btn('+ '+a,'admin:'+a,'small')).join('')}</div>`)}${card('Registration requests',registrationTable(),link('View all','Registrations'),'full')}${card('Room availability',roomTable(),link('Manage rooms','Rooms & Beds'),'full')}${card('Recent admin activity',`${promotionAudit.length?promotionAuditMarkup():''}<div class="announcement"><strong>24 students allocated to Maple House</strong><small>Today, 9:15 AM · Ananya Rao</small></div><div class="announcement"><strong>Academic year 2026–27 activated</strong><small>Yesterday, 4:30 PM · Ananya Rao</small></div><div class="announcement"><strong>New warden assigned to Cedar House</strong><small>Yesterday, 11:20 AM · Ananya Rao</small></div>`,link('Audit logs','Audit Logs'),'full')}</div>`;}
function mentees(){return `<div class="mentees">${academicStudents.slice(0,3).map((s,i)=>`<article class="mentee"><span class="avatar">${s.name.split(' ').map(p=>p[0]).slice(0,2).join('')}</span><h4>${esc(s.name)}</h4><p>${s.course} ? Year ${s.studyYear} ? ${s.academicYear}</p><p>${s.allocation?'Room '+s.allocation.room:'Awaiting room allocation'}</p><p>Next session<br><strong>${['28 Sep, 3:00 PM','28 Sep, 4:30 PM','30 Sep, 11:00 AM'][i]}</strong></p>${btn('View profile','mentee:'+esc(s.name),'small')}</article>`).join('')}</div>`;}
function sessionTable(){return table(['Student','Topic','Preferred date / time','Message','Actions'],sessions.filter(s=>s.status==='Pending').map(s=>[s.name,esc(s.topic),esc(s.date),esc(s.message),`<div class="action-group">${btn('Accept','accept:'+sessions.indexOf(s),'small primary')}${btn('Suggest time','reschedule:'+sessions.indexOf(s),'small')}</div>`]));}
function agenda(){return `<div class="agenda-item"><span class="agenda-time">28 SEP<br>10:00 AM</span><div><strong>Settling into the new semester</strong><p>Aditya Kumar · Mentor office</p></div></div>${sessions.filter(s=>s.status==='Accepted').map(s=>`<div class="agenda-item"><span class="agenda-time">${esc(s.date)}</span><div><strong>${esc(s.topic)}</strong><p>${s.name} · Mentor office</p></div></div>`).join('')}<div class="agenda-item"><span class="agenda-time">30 SEP<br>2:00 PM</span><div><strong>Study skills check-in</strong><p>Group session · Seminar room 2</p></div></div>`;}
function resourceList(){return resources.map((r,i)=>`<div class="resource"><span class="icon-box">${icon('file')}</span><div><strong>${esc(r[0])}</strong><p>${esc(r[1])}</p></div>${btn('Open','resource:'+i,'small')}</div>`).join('');}
function mentorDashboard(){return summary([['Assigned Students','3','Academic year 2026–27'],['Pending Session Requests',sessions.filter(s=>s.status==='Pending').length,'Ready for your response'],['Sessions This Week',2+sessions.filter(s=>s.status==='Accepted').length,'Upcoming conversations']])+`<div class="stack">${card('My mentees',mentees(),link('View students','My Students'))}${card('Session requests',sessionTable(),link('View all','Session Requests'))}<div class="dashboard-grid">${card('Upcoming sessions',agenda(),link('Schedule','Schedule'))}${card('Guidance & resources',resourceList(),btn('+ Share resource','resource-add','small'))}</div></div>`;}
function secondary(){if(page==='Year Promotion'&&role==='Admin')return promotionPage();if(page==='Announcements')return card('Hostel announcements',announcementBody(),role==='Warden'?btn('+ Create announcement','announcement','primary small'):'');if(page==='Complaints')return card('Complaints',complaintTable(role==='Student'),role==='Student'?btn('+ Raise complaint','complaint','primary small'):'');if(page==='Pass Requests')return card('Long Pass requests',passTable());if(page==='Registrations')return card('Registration requests',registrationTable());if(page==='Gate Activity'||page==='Entry / Exit')return card(page,gateTable(role==='Student'));if(page==='Session Requests')return card(page,sessionTable());if(page==='Schedule')return card('Upcoming sessions',agenda());if(page==='My Students')return card('My assigned students',mentees());if(page==='Resources')return card('Approved guidance resources',resourceList(),btn('+ Share resource','resource-add','small'));if(page==='Rooms & Beds'||page==='Hostels')return card('Room Map',roomMapCard(),'','full')+card(page,roomTable(),btn('+ Add '+(page==='Hostels'?'Hostel':'Room'),'admin:Add '+(page==='Hostels'?'Hostel':'Room'),'primary small'))+(page==='Rooms & Beds'?card('Room-level capacity',roomCapacityTable()):'');if(page==='My Room')return studentRoomPage();if(page==='Mentor')return card('Dr. Meera Nair',`<p>Department of Computer Science · Your assigned mentor</p>${btn('Request session','session','primary')}<h4>Your session requests</h4>${table(['Topic','Date / time','Status'],sessions.filter(s=>s.name==='Aarav Sharma').map(s=>[esc(s.topic),esc(s.date),badge(s.status)]))}`);if(page==='Passes')return studentPassPage();if(page==='Documents'&&role==='Student')return studentDocumentsPage();if(page==='Profile'||page==='Settings')return card(page,`<form id="profile-form" class="form-grid"><div><label for="profile-name">Name</label><input id="profile-name" value="${esc(roles[role].name)}" required></div><div><label for="profile-email">Institution email</label><input id="profile-email" type="email" value="${role==='Student'?esc(currentStudent().email):role.toLowerCase()+'@example.edu'}" required></div><div class="span-2"><button class="btn primary">Save demo profile</button></div></form>`);if(page==='Reports')return card('Institutional reports',`<p>Download the current demo accommodation summary.</p>${btn('Generate accommodation report','report','primary')}`);if(page==='Academic Years')return card('Year promotion',`<p>Verify uploaded marksheets, promote students and release their previous beds.</p>${link('Open Year Promotion','Year Promotion')}`)+card(page,table(['Academic year','Status','Start','End'],[['2026–27',badge('Active'),'July 2026','June 2027'],['2025–26',badge('Archived'),'July 2025','June 2026']]));if(page==='Audit Logs')return card('Academic progression audit',promotionAuditMarkup())+card(page,table(['Action','Actor','Time'],[['Academic year activated','Ananya Rao','24 Sep, 4:30 PM'],['Warden assignment updated','Ananya Rao','24 Sep, 11:20 AM']]));if(page==='Wardens'||page==='Mentors')return card(page,table(['Name','Assignment','Status'],page==='Wardens'?[['R. Krishnan','Maple House',badge('Active')]]:[['Dr. Meera Nair','3 assigned students',badge('Active')]]),btn('+ '+(page==='Wardens'?'Add Warden':'Create Mentor'),'admin:'+(page==='Wardens'?'Add Warden':'Create Mentor'),'small primary'));if(page==='Residents'||page==='Students'||page==='Allocations')return card(page,`<div class="section-toolbar"><div><label for="student-search">Search students</label><input id="student-search" placeholder="Search name or room"></div></div><div id="student-results">${residentTable('')}</div>`,page==='Allocations'?btn('Allocate student','admin:Allocate Student','primary small'):'');return '';}
function residentTable(q){return table(['Student','College ID','Course / Year','Hostel','Room','Academic year'],academicStudents.filter(s=>[s.name,s.id,s.allocation?.room||''].join(' ').toLowerCase().includes(q.toLowerCase())).map(s=>[esc(s.name),s.id,s.course+' / Year '+s.studyYear,s.allocation?.hostel||'Awaiting allocation',s.allocation?.room||'Not allocated',s.academicYear]));}
function dashboard(){const u=roles[role],ni=['home','users','pass','message','out','users','file','bell','settings'];document.getElementById('app').innerHTML=`<div class="app-shell ${collapsed?'collapsed':''}"><aside class="sidebar" aria-label="${role} navigation">${brand()}<div class="nav-label">${role.toUpperCase()} WORKSPACE</div><nav>${u.nav.map((n,i)=>`<button class="side-link ${page===n?'active':''}" data-page="${n}" ${page===n?'aria-current="page"':''}>${icon(ni[i%ni.length])}<span>${n}</span></button>`).join('')}</nav><div class="side-bottom"><button class="side-link" data-action="preferences">${icon('settings')}<span>Settings</span></button><button class="side-link" data-action="logout">${icon('out')}<span>Log out</span></button><div class="user-block"><span class="avatar">${u.initials}</span><div class="user-text"><strong>${esc(u.name)}</strong><small>${role}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><button class="icon-button" data-action="sidebar" aria-label="Toggle sidebar">${icon('menu')}</button><h2>${page}</h2></div><div class="topbar-right"><label class="demo-label" for="role-select">PREVIEW ROLE</label><select class="demo-select" id="role-select" aria-label="Preview role">${Object.keys(roles).map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><button class="avatar" data-action="preferences" aria-label="Profile settings">${u.initials}</button></div></header><main class="dashboard"><div class="welcome"><div><span class="eyebrow" style="font-size:12px">${role==='Admin'?'INSTITUTION OVERVIEW':role==='Mentor'?'A LITTLE GUIDANCE. A LASTING DIFFERENCE.':(role==='Student'?esc((currentStudent().allocation?.hostel||'Awaiting allocation')+' / Academic year '+currentStudent().academicYear):'Maple House / Academic year 2026-27')}</span><h1>${page==='Dashboard'?(role==='Student'?'Good morning, Aarav':role==='Warden'?'Your hostel, at a glance.':role==='Admin'?'A connected campus. A clear overview.':'Welcome back, Dr. Meera'):page}</h1><p>${role==='Student'?"Here's what's happening with your hostel account.":role==='Warden'?'A clear view of what needs your attention today.':role==='Admin'?'Your institution’s accommodation and operations, in one place.':'Help your students find their way forward.'}</p></div>${role==='Student'?btn(icon('alert')+' Emergency / SOS','sos','danger small'):'<span class="date">Friday, 25 September 2026</span>'}</div>${page==='Dashboard'?({Student:studentDashboard,Warden:wardenDashboard,Admin:adminDashboard,Mentor:mentorDashboard}[role])():secondary()}<p class="demo-notice">Interactive frontend preview · Fictional data · Changes last until refresh · No live authentication</p></main></div></div>`;}
function route(){let parts=location.hash.slice(1).split('/');if(parts[0]==='demo'&&roles[parts[1]]){role=parts[1];page=decodeURIComponent(parts[2]||'Dashboard');if(!roles[role].nav.includes(page))page='Dashboard';dashboard();window.scrollTo?.({top:0,behavior:'instant'});}else{landing();if(parts[0])requestAnimationFrame(()=>document.getElementById(parts[0])?.scrollIntoView());}observeReveals();}
function observeReveals(){if(!('IntersectionObserver' in window))return;const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal');observer.unobserve(entry.target);}}),{threshold:.1});document.querySelectorAll('.feature-card,.security-item,.step').forEach(el=>observer.observe(el));}
let lastFocus;function modal(title,body){lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal input,.modal select,.modal button')?.focus();}
function close(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
let toastTimer;function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4500);}
const field=(name,label,type='text',extra='')=>`<div><label for="f-${name}">${label}</label><input name="${name}" id="f-${name}" type="${type}" required ${extra}></div>`;
function formModal(title,type,fields,submit='Submit request'){modal(title,`<form data-form="${type}">${fields}<button class="btn primary" type="submit">${submit}</button><p class="modal-note">Interactive demo only. Nothing is sent to your institution.</p></form>`);}
function action(a){let [kind,id]=a.split(':');if(kind.startsWith('promotion-')||kind.startsWith('marksheet-'))return promotionAction(kind,id);if(kind==='quick-pass'||kind==='qr')return openQuickPass();if(kind==='long-pass'||kind==='pass')return openLongPass();if(kind==='explore-role')return showRoleStory(id);if(kind==='close')return close();if(kind==='public-menu')return document.querySelector('.nav-links').classList.toggle('open');if(kind==='sidebar'){if(innerWidth<=720)document.querySelector('.app-shell').classList.toggle('drawer-open');else{collapsed=!collapsed;dashboard();}return;}if(kind==='login')return modal('Welcome to Hostel Ops',`<p>Choose one of the four roles to explore the frontend.</p><form data-form="login"><div><label for="login-role">Role</label><select id="login-role" name="role">${Object.keys(roles).map(r=>`<option>${r}</option>`).join('')}</select></div><button class="btn primary">Enter demo workspace ${icon('arrow')}</button><p class="modal-note">This is a role preview, not a secure login. Production authentication must be connected to your institution.</p></form>`);if(kind==='register')return registrationForm();if(kind==='logout'){close();location.hash='home';return;}if(kind==='privacy')return modal('Privacy by design',`<p>This prototype uses fictional dashboard records and keeps interactions in browser memory. No contact or registration details are transmitted.</p><p>Guardian information is emergency contact data only. There is no guardian login. Production deployment requires institutional privacy terms, secure storage and server-side role enforcement.</p>`);if(kind==='complaint')return formModal('Raise a complaint','complaint','<div><label for="category">Category</label><select id="category" name="category"><option>Plumbing</option><option>Electrical</option><option>Wi-Fi connectivity</option><option>Housekeeping</option><option>Other</option></select></div>'+field('description','Describe the issue'));if(kind==='session')return formModal('Request a mentoring session','session',field('topic','Topic')+field('date','Preferred date and time','datetime-local')+field('message','Message for your mentor'));if(kind==='sos')return modal('Emergency assistance',`<p>This demo cannot contact emergency services or your warden. If you need immediate help, use your phone to contact local emergency services or your institution.</p><p>Preview the confirmation flow for notifying the hostel emergency team.</p>${btn('Confirm demo SOS','confirm-sos','danger')}`);if(kind==='confirm-sos'){close();return toast('Demo SOS confirmed. No emergency alert was sent.');}if(kind==='office'||kind==='contact-student'||kind==='guardian')return modal(kind==='guardian'?'Guardian emergency contact':kind==='office'?'Hostel office':'Student contact',`<p>${kind==='guardian'?'Karan Joshi · Guardian: Sanjay Joshi':kind==='office'?'R. Krishnan · Maple House warden':'Karan Joshi · Room B-208'}</p><p>Contact details are withheld in this fictional preview. A production system will show the verified institutional contact here.</p>${kind==='guardian'?'<p class="modal-note">Emergency contact information is restricted to authorized hostel staff. Guardians do not have an account.</p>':''}`);if(kind==='notifications')return modal('Notifications',announcementBody());if(kind==='preferences')return formModal('Workspace preferences','preferences','<div><label for="notify">Email notifications</label><select id="notify"><option>Important updates</option><option>All updates</option></select></div>','Save preferences');if(kind==='approve'||kind==='reject')return modal(kind==='approve'?'Approve this pass?':'Reject this pass?',`<p>${passes[id].name} · ${esc(passes[id].reason)}<br>${passes[id].departure} → ${passes[id].return}</p>${btn('Confirm '+kind,`confirm-${kind}:${id}`,kind==='reject'?'danger':'primary')}`);if(kind==='confirm-approve'||kind==='confirm-reject'){passes[id].status=kind==='confirm-approve'?'Approved':'Rejected';close();dashboard();return toast('Pass '+passes[id].status.toLowerCase()+' in demo.');}if(kind==='pass-detail')return modal('Pass request details',`<p>${passes[id].name} · Room ${passes[id].room}</p><p>Reason: ${esc(passes[id].reason)}${passes[id].destination?'<br>Destination: '+esc(passes[id].destination):''}${passes[id].contact?'<br>Leave contact: '+esc(passes[id].contact):''}<br>Departure: ${passes[id].departure}<br>Expected return: ${passes[id].return}</p>${badge(passes[id].status)}`);if(kind==='update')return formModal('Update '+id,'update:'+id,'<div><label for="status">Complaint status</label><select id="status" name="status"><option>Open</option><option>In progress</option><option>Resolved</option></select></div>','Save update');if(kind==='announcement')return formModal('Create hostel announcement','announcement',field('title','Announcement title')+field('body','Announcement message'),'Publish demo announcement');if(kind==='documents')return modal('Document review',`<p>College identity card · Hostel application</p>${badge('Pending')}<p>No real student documents are included in this preview. Production review will use protected document access.</p>`);if(kind==='review')return modal('Review registration',`<p>${registrations[id][0]} · ${registrations[id][1]}</p><ul class="checklist"><li>Verify institutional identity</li><li>Review submitted documents</li><li>Confirm academic year and course</li></ul><p class="modal-note">Demo documents are placeholders. These actions change only the sample status.</p><div class="action-group">${btn('Approve demo','registration-approve:'+id,'primary')}${btn('Reject demo','registration-reject:'+id,'danger')}</div>`);if(kind==='registration-approve'||kind==='registration-reject'){registrations[id][5]=kind==='registration-approve'?'Approved':'Rejected';close();dashboard();return toast('Registration status updated in demo.');}if(kind==='accept'){sessions[id].status='Accepted';dashboard();return toast('Session accepted in demo and added to agenda.');}if(kind==='reschedule')return formModal('Suggest a different time','reschedule:'+id,field('date','Proposed date and time','datetime-local'),'Send demo suggestion');if(kind==='resource-add')return formModal('Share an approved resource','resource-add',field('title','Resource title')+field('url','Approved resource URL','url'),'Share with assigned students');if(kind==='resource')return modal(esc(resources[id][0]),`<p>${esc(resources[id][1])}</p><p>${resources[id][2]?esc(resources[id][2]):'Guidance: establish a steady weekly routine, leave room for rest, and reach out to your mentor when you need support.'}</p>`);if(kind==='mentee')return modal(esc(id),'<p>Assigned mentee · Academic year 2026–27</p><p>Academic interests: coursework planning and study skills.</p><p>Use session requests and approved resources to support this student.</p>');if(kind==='admin'){if(id==='Year Promotion'){location.hash='demo/Admin/Year%20Promotion';return;}if(id==='Generate Report')return action('report');return formModal(id,'admin:'+id,id==='Add Hostel'?field('name','Hostel name')+field('capacity','Total bed capacity','number','min="1"'):id==='Add Room'?field('hostel','Hostel')+field('room','Room number')+field('beds','Beds','number','min="1"'):id==='Allocate Student'?field('student','College ID')+field('hostel','Hostel')+field('room','Room and bed'):field('name','Full name')+field('email','Institution email','email'),'Preview '+id.toLowerCase());}if(kind==='rm-hostel'){roomMapHostel=id;dashboard();return;}
  if(kind==='rm-filter'){roomMapFilter=id;dashboard();return;}
  if(kind==='rm-bed'){
    const s=studentById(id);
    if(!s)return;
    modal(esc(s.name),'<p>'+esc(s.id)+'</p><dl class="rm-modal-dl"><dt>Course</dt><dd>'+esc(s.course)+'</dd><dt>Year</dt><dd>Year '+s.studyYear+' of '+s.duration+'</dd><dt>Academic year</dt><dd>'+esc(s.academicYear)+'</dd><dt>Room</dt><dd>'+(s.allocation?esc(s.allocation.hostel)+' / '+esc(s.allocation.room)+' / Bed '+s.allocation.bed:'Awaiting allocation')+'</dd><dt>Preferred mess</dt><dd>'+esc(s.mess)+'</dd></dl>');
    return;
  }
  if(kind==='rm-vacant'){
    const [h,r,b]=id.split('|');
    modal('Vacant bed','<p>'+esc(h)+' · Room '+esc(r)+' · Bed '+esc(b)+'</p><p>This bed is currently unoccupied and ready for allocation.</p>'+btn('Allocate student','admin:Allocate Student','primary'));
    return;
  }
  if(kind==='report'){const blob=new Blob(['Hostel,Total Beds,Occupied,Available,Maintenance\n'+hostelInventory().map(h=>[h.name,h.total,h.occupied,h.available,h.maintenance].join(',')).join('\n')],{type:'text/csv'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hostel-ops-demo-accommodation.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo accommodation report downloaded.');}}
 document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)action(a.dataset.action);const n=e.target.closest('[data-page]');if(n){document.querySelector('.app-shell')?.classList.remove('drawer-open');page=n.dataset.page;location.hash='demo/'+role+'/'+encodeURIComponent(page);}if(e.target.classList.contains('overlay'))close();});
 document.addEventListener('change',e=>{if(e.target.id==='role-select')location.hash='demo/'+e.target.value+'/Dashboard';});
 document.addEventListener('input',e=>{if(e.target.id==='student-search')document.getElementById('student-results').innerHTML=residentTable(e.target.value);});
 document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(await handlePromotionSubmit(f,d))return;if(f.id==='contact-form'){modal('Your enquiry preview',`<p><strong>${esc(d.name)}</strong> · ${esc(d.institution)}</p><p>${esc(d.email)}</p><p>${esc(d.message)}</p><p class="modal-note">Enquiry previewed successfully. Delivery is not connected; nothing was sent.</p>`);return;}if(f.id==='profile-form'){roles[role].name=document.getElementById('profile-name').value;if(role==='Student'){currentStudent().name=roles[role].name;currentStudent().email=document.getElementById('profile-email').value;}dashboard();return toast('Demo profile saved.');}const [type,id]=(f.dataset.form||'').split(':');if(type==='quick-pass'){const result=createQuickPass(d.movement);if(result.error){toast(result.error);return;}document.getElementById('quick-result').innerHTML=quickQRMarkup();refreshQuickUI();toast('Demo '+d.movement.toLowerCase()+' QR generated. Not valid at a real gate.');return;}if(type==='login'){close();location.hash='demo/'+d.role+'/Dashboard';return;}if(type==='pass'){const dateError=validateLongPassDates(d.departure,d.return);if(dateError){showLongPassError(dateError);return;}passes.push({name:'Aarav Sharma',room:'A-204',type:'Long Pass',reason:d.reason,destination:d.destination,contact:d.contact,departure:d.departure.replace('T',' '),return:d.return.replace('T',' '),status:'Pending'});}if(type==='complaint')complaints.unshift({id:'CMP-'+(287+complaints.length),student:'Aarav / A-204',category:d.category,description:d.description,status:'Open',priority:'Normal',date:'25 Sep 2026'});if(type==='session')sessions.push({name:'Aarav Sharma',topic:d.topic,date:d.date.replace('T',' '),message:d.message,status:'Pending'});if(type==='update')complaints.find(c=>c.id===id).status=d.status;if(type==='announcement')announcements.unshift([d.title,d.body,'Just now · Hostel office']);if(type==='reschedule'){sessions[id].date=d.date.replace('T',' ');sessions[id].status='Proposed';}if(type==='resource-add')resources.unshift([d.title,'Approved guidance · Shared just now',d.url]);close();if(location.hash.startsWith('#demo'))dashboard();if(type==='register')registrationPreview(d);else if(type==='admin')modal(id+' preview',`<p>${Object.entries(d).map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>')}</p><p class="modal-note">Ready for backend integration. No institutional record was created.</p>`);else if(type==='pass')toast('Long Pass sent to the demo warden approval queue.');else toast(type==='reschedule'?'Alternative time suggested in demo.':'Saved successfully in this demo.');});
 document.addEventListener('keydown',e=>{const m=document.querySelector('.modal');if(!m){if(e.key==='Escape')document.querySelector('.app-shell')?.classList.remove('drawer-open');return;}if(e.key==='Escape')close();if(e.key==='Tab'){const els=[...m.querySelectorAll('button,input,select,textarea,a[href]')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 window.addEventListener('hashchange',route);route();

function registrationForm(){
 modal('Make yourself at home.', `<div class="registration-intro"><span class="eyebrow">STUDENT REGISTRATION</span><p>Your campus journey begins here. Tell us about yourself and the mess you would like to join.</p></div><form data-form="register" class="registration-form">
 <fieldset><legend><span>01</span> Institution & academics</legend><div class="form-grid">${field('invitation','Institution invitation code')}${field('college','College ID')}${field('course','Course')}${field('branch','Branch / department')}<div><label for="f-year">Year of study</label><select id="f-year" name="year" required><option value="">Select your year</option><option>1st year</option><option>2nd year</option><option>3rd year</option><option>4th year</option><option>5th year or above</option><option>Postgraduate / Research</option></select></div>${field('academic','Academic year','text','placeholder="e.g. 2026?27"')}</div></fieldset>
 <fieldset><legend><span>02</span> Your details</legend><div class="form-grid">${field('name','Full name')}${field('email','Institution email','email')}${field('phone','Student mobile number','tel')}${field('guardianName','Guardian / emergency contact name')}${field('guardian','Guardian / emergency contact number','tel')}</div></fieldset>
 <fieldset class="mess-preference"><legend><span>03</span> Your mess preference</legend><label for="f-mess">Preferred mess</label><input id="f-mess" name="mess" required maxlength="100" placeholder="Enter the name of one mess you want to join" aria-describedby="mess-help"><p id="mess-help" class="field-help">Specify one mess by name. This is your preference; final availability and allocation will be confirmed by your institution.</p></fieldset>
 <button class="btn primary" type="submit">Review my registration ${icon('arrow')}</button><p class="modal-note">Frontend preview only. Invitation verification and registration storage are not connected. Guardian details are emergency contact information, not a separate login.</p></form>`);
 document.querySelector('.modal')?.classList.add('registration-modal');
}
function registrationPreview(d){
 const fields=[['Full name',d.name],['Institution email',d.email],['Student mobile',d.phone],['College ID',d.college],['Course / branch',d.course+' / '+d.branch],['Year of study',d.year],['Academic year',d.academic],['Emergency contact',d.guardianName+' ? '+d.guardian]];
 modal('Your registration preview',`<p>Review your student details and mess preference.</p><dl class="registration-review">${fields.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="mess-summary"><span class="eyebrow">PREFERRED MESS</span><h3>${esc(d.mess)}</h3><p>Preference recorded in this preview. Allocation is subject to institutional confirmation.</p></div><p class="modal-note">Nothing has been submitted or saved to a database. This is a frontend preview.</p>${btn('Done','close','primary')}`);
}

function roleExplorer(){
 return `<section class="role-explorer" aria-labelledby="role-explorer-title"><div class="role-explorer-heading"><span class="eyebrow">ONE CAMPUS. FOUR CONNECTED WORKSPACES.</span><h2 id="role-explorer-title">Made for your day.</h2><p>Less friction for students. More clarity for your team.</p></div><div class="role-tabs" role="group" aria-label="Explore workspaces">${Object.keys(roles).map((r,i)=>`<button class="role-tab ${i===0?'selected':''}" aria-pressed="${i===0}" data-action="explore-role:${r}">${icon(r==='Student'?'home':r==='Warden'?'shield':r==='Admin'?'chart':'users')}${r}</button>`).join('')}</div><div id="role-story">${roleStory('Student')}</div></section>`;
}
function roleStory(r){
 const data={Student:['Your campus life, in your pocket.','A room to call home. A Quick Pass to head out. A mentor to help you move forward.',['Quick & Long Passes','Room & mess details','Support & mentoring'],'qr'],Warden:['See what matters. Act with confidence.','Review long-leave requests, follow up on overdue returns and keep your hostel running smoothly.',['Pass approvals','Resident support','Hostel announcements'],'shield'],Admin:['Every hostel. One clear view.','Bring registration, room allocation and institutional reporting into a single organized workspace.',['Registration review','Room & bed planning','Administrative reports'],'chart'],Mentor:['Meaningful support starts here.','Stay connected with assigned students, arrange conversations and share helpful guidance.',['Assigned mentees','Session scheduling','Approved resources'],'users']}[r];
 return `<div class="role-story"><div class="role-story-icon">${icon(data[3])}</div><div><span class="eyebrow">${r.toUpperCase()} WORKSPACE</span><h3>${data[0]}</h3><p>${data[1]}</p><div class="role-benefits">${data[2].map(t=>`<span>${icon('check')}${t}</span>`).join('')}</div></div></div>`;
}
function showRoleStory(r){
 if(!roles[r])return;
 document.getElementById('role-story').innerHTML=roleStory(r);
 document.querySelectorAll('.role-tab').forEach(el=>{const selected=el.dataset.action==='explore-role:'+r;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});
}
if(typeof window.setInterval==='function')window.setInterval(refreshQuickUI,1000);
